INSERT INTO public.totvs_mayor_periodos_estado(periodo,estado,fundamento,origen)
VALUES
  ('2026-09-01','PROVISIONAL_CIERRE_POR_CONFIRMAR','Cierre de septiembre no confirmado; no equivale a cierre contable','REVISION_MAYOR_2026-10-06'),
  ('2026-10-01','PARCIAL','El archivo revisado contiene movimientos solo hasta 2026-10-05','REVISION_MAYOR_2026-10-06')
ON CONFLICT (periodo) DO NOTHING;

DO $$
DECLARE v_total integer; v_propuestas integer; v_revision integer;
BEGIN
  SELECT count(*),count(*) FILTER (WHERE estado='PROPUESTA'),count(*) FILTER (WHERE estado='REVISION')
  INTO v_total,v_propuestas,v_revision
  FROM public.totvs_mayor_cuentas_clasificacion
  WHERE version=1 AND origen='clasificacion_preliminar_cuentas_mayor.xlsx@bcb5f334e2f3186d981e06d90caaa47646b42c3ff72c2d6d1bdeb2fd34b916ff';
  IF v_total <> 251 OR v_propuestas <> 217 OR v_revision <> 34 THEN
    RAISE EXCEPTION 'El mapa preliminar del Mayor no concilia: total %, propuestas %, revision %',v_total,v_propuestas,v_revision;
  END IF;
END;
$$;

COMMIT;
